import{_ as e,o,c as r,a2 as n}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Filter Conditions","description":"Which filter conditions are available for which column type.","frontmatter":{"title":"Filter Conditions","description":"Which filter conditions are available for which column type."},"headers":[],"relativePath":"en/referenz/filterbedingungen.md","filePath":"en/referenz/filterbedingungen.md","lastUpdated":1787319236000}'),a={name:"en/referenz/filterbedingungen.md"};function d(s,t,i,l,c,h){return o(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="filter-conditions-—-reference" tabindex="-1">Filter Conditions — Reference <a class="header-anchor" href="#filter-conditions-—-reference" aria-label="Permalink to &quot;Filter Conditions — Reference&quot;">​</a></h1><p>Which conditions a filter offers depends on the <strong>column type</strong>. This reference maps the two to each other.</p><p>A filter is built as <strong>Field</strong> → <strong>Condition</strong> → <strong>Value</strong>, introduced with <em>If</em>.</p><p>→ <a href="/en/ansichten/filtern-sortieren-gruppieren">Filtering, Sorting, Grouping</a></p><hr><h2 id="all-conditions" tabindex="-1">All conditions <a class="header-anchor" href="#all-conditions" aria-label="Permalink to &quot;All conditions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Condition</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>equals</strong></td><td>Exact match</td></tr><tr><td><strong>does not equal</strong></td><td>Anything except this value</td></tr><tr><td><strong>contains</strong></td><td>Substring occurs</td></tr><tr><td><strong>does not contain</strong></td><td>Substring does not occur</td></tr><tr><td><strong>is less than</strong></td><td>Numeric comparison</td></tr><tr><td><strong>is greater than</strong></td><td>Numeric comparison</td></tr><tr><td><strong>is before</strong></td><td>Chronological comparison</td></tr><tr><td><strong>is after</strong></td><td>Chronological comparison</td></tr><tr><td><strong>includes any of</strong></td><td>At least one of the selected options</td></tr><tr><td><strong>includes none of</strong></td><td>None of the selected options</td></tr><tr><td><strong>includes all of</strong></td><td>All of the selected options</td></tr><tr><td><strong>is</strong></td><td>Person-based comparison</td></tr><tr><td><strong>is not</strong></td><td>Person-based comparison</td></tr><tr><td><strong>is empty</strong></td><td>No value present</td></tr><tr><td><strong>is not empty</strong></td><td>Some value present</td></tr></tbody></table><h2 id="the-same-conditions-as-an-expression" tabindex="-1">The same conditions as an expression <a class="header-anchor" href="#the-same-conditions-as-an-expression" aria-label="Permalink to &quot;The same conditions as an expression&quot;">​</a></h2><p>Internally, a filter is an <a href="/en/apptivescript/was-ist-apptivescript">ApptiveScript</a> expression. The dialog writes it for you — each condition corresponds to a function:</p><table tabindex="0"><thead><tr><th>Condition</th><th>Function</th></tr></thead><tbody><tr><td>equals · does not equal</td><td><code>isEqualTo</code> · <code>isNotEqualTo</code></td></tr><tr><td>contains</td><td><code>contains</code></td></tr><tr><td>is less than · is greater than</td><td><code>smallerThan</code> · <code>greaterThan</code></td></tr><tr><td>is before · is after</td><td><code>before</code> · <code>after</code></td></tr><tr><td>includes any of · none of · all of</td><td><code>includesAnyOf</code> · <code>includesNoneOf</code> · <code>includesAllOf</code></td></tr><tr><td>is · is not (person)</td><td><code>isActor</code></td></tr><tr><td>is empty · is not empty</td><td><code>isEmpty</code> · <code>isNotEmpty</code></td></tr><tr><td>and · or</td><td><code>logicalAnd</code> · <code>logicalOr</code></td></tr><tr><td>does not contain</td><td><code>contains</code>, negated with <code>isFalse</code></td></tr></tbody></table><p>You never need to know this just to filter. It helps in two places: reading a <a href="/en/grids/berechnete-felder#formula">Formula</a>, and writing a <a href="/en/apptivescript/bedingungen">Condition</a> for a block&#39;s visibility or a Flow transition — the same names apply there.</p><hr><h2 id="mapping-by-column-type" tabindex="-1">Mapping by column type <a class="header-anchor" href="#mapping-by-column-type" aria-label="Permalink to &quot;Mapping by column type&quot;">​</a></h2><h3 id="text-and-text-like-types" tabindex="-1">Text and text-like types <a class="header-anchor" href="#text-and-text-like-types" aria-label="Permalink to &quot;Text and text-like types&quot;">​</a></h3><p><strong>Text</strong>, <strong>E-Mail</strong>, <strong>Phone Number</strong>, <strong>Weblink</strong></p><table tabindex="0"><thead><tr><th>Condition</th><th></th></tr></thead><tbody><tr><td>equals</td><td>does not equal</td></tr><tr><td>contains</td><td>does not contain</td></tr><tr><td>is empty</td><td>is not empty</td></tr></tbody></table><h3 id="numbers" tabindex="-1">Numbers <a class="header-anchor" href="#numbers" aria-label="Permalink to &quot;Numbers&quot;">​</a></h3><p><strong>Number</strong>, <strong>Decimal</strong>, <strong>Currency</strong></p><table tabindex="0"><thead><tr><th>Condition</th><th></th></tr></thead><tbody><tr><td>equals</td><td>does not equal</td></tr><tr><td>is less than</td><td>is greater than</td></tr><tr><td>is empty</td><td>is not empty</td></tr></tbody></table><h3 id="date" tabindex="-1">Date <a class="header-anchor" href="#date" aria-label="Permalink to &quot;Date&quot;">​</a></h3><p><strong>Date</strong>, <strong>Date and time</strong>, <strong>Created at</strong></p><table tabindex="0"><thead><tr><th>Condition</th><th></th></tr></thead><tbody><tr><td>equals</td><td>does not equal</td></tr><tr><td>is before</td><td>is after</td></tr><tr><td>is empty</td><td>is not empty</td></tr></tbody></table><p>For date fields, you can choose a <strong>relative expression</strong> instead of a fixed date:</p><table tabindex="0"><thead><tr><th>Expression</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>exact date</strong></td><td>A specific day</td></tr><tr><td><strong>today</strong></td><td>The current day</td></tr><tr><td><strong>tomorrow</strong> / <strong>yesterday</strong></td><td>Relative to the current day</td></tr><tr><td><strong>X days ago</strong></td><td>X days in the past</td></tr><tr><td><strong>in X days</strong></td><td>X days in the future</td></tr></tbody></table><p>These are expressions too: <em>today</em> is <code>today()</code>, <em>yesterday</em> is <code>today().subtractDays(1)</code>.</p><div class="tip custom-block"><p class="custom-block-title">Relative filters don&#39;t age</p><p>A filter with <code>Due on</code> <em>is before</em> <em>today</em> permanently shows overdue entries — without anyone having to maintain it. A fixed date would already be wrong tomorrow.</p><p>That&#39;s the difference between a view you set up once and one you have to keep touching.</p></div><h3 id="checkmark" tabindex="-1">Checkmark <a class="header-anchor" href="#checkmark" aria-label="Permalink to &quot;Checkmark&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Condition</th><th></th></tr></thead><tbody><tr><td>equals</td><td>does not equal</td></tr><tr><td>is empty</td><td>is not empty</td></tr></tbody></table><h3 id="single-select" tabindex="-1">Single Select <a class="header-anchor" href="#single-select" aria-label="Permalink to &quot;Single Select&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Condition</th><th></th></tr></thead><tbody><tr><td>equals</td><td>does not equal</td></tr><tr><td>is empty</td><td>is not empty</td></tr></tbody></table><h3 id="multiple-select" tabindex="-1">Multiple Select <a class="header-anchor" href="#multiple-select" aria-label="Permalink to &quot;Multiple Select&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Condition</th><th></th></tr></thead><tbody><tr><td>includes any of</td><td>includes none of</td></tr><tr><td>includes all of</td><td></td></tr><tr><td>is empty</td><td>is not empty</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">The difference matters</p><ul><li><strong>includes any of</strong> — at least one of the selected options applies</li><li><strong>includes all of</strong> — all of the selected options must apply</li><li><strong>includes none of</strong> — none of them apply</li></ul><p>For tags, <em>includes any of</em> is usually what&#39;s meant. <em>includes all of</em> is much stricter and often returns fewer matches than expected.</p></div><h3 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h3><p><strong>Link record</strong></p><table tabindex="0"><thead><tr><th>Condition</th><th></th></tr></thead><tbody><tr><td>is empty</td><td>is not empty</td></tr></tbody></table><p><strong>Link multiple records</strong></p><table tabindex="0"><thead><tr><th>Condition</th><th></th></tr></thead><tbody><tr><td>includes any of</td><td>includes none of</td></tr><tr><td>includes all of</td><td></td></tr><tr><td>is empty</td><td>is not empty</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Finding data gaps</p><p><code>Customer</code> <em>is empty</em> shows all entries without an assignment — the fastest way to find incomplete records, especially after a <a href="/en/grids/csv-import">CSV import</a> that couldn&#39;t establish links.</p></div><h3 id="person-related-types" tabindex="-1">Person-related types <a class="header-anchor" href="#person-related-types" aria-label="Permalink to &quot;Person-related types&quot;">​</a></h3><p><strong>User</strong>, <strong>Created by</strong></p><table tabindex="0"><thead><tr><th>Condition</th><th></th></tr></thead><tbody><tr><td>is</td><td>is not</td></tr><tr><td>is empty</td><td>is not empty</td></tr></tbody></table><p>Besides specific people, the expression <strong>current user</strong> is also available as a value.</p><div class="tip custom-block"><p class="custom-block-title">One view for everyone</p><p><code>Assigned to</code> <em>is</em> <em>current user</em> creates a view that automatically shows each person their own entries. You don&#39;t need a separate view per team member.</p></div><p>For <strong>Created by</strong>, the values <em>Form link</em> and <em>API Credentials</em> can also appear — for entries that didn&#39;t come from a human.</p><h3 id="other-types" tabindex="-1">Other types <a class="header-anchor" href="#other-types" aria-label="Permalink to &quot;Other types&quot;">​</a></h3><p><strong>Files</strong>, <strong>Address</strong>, <strong>Geolocation</strong>, <strong>Signature</strong>, <strong>Internal Link</strong></p><table tabindex="0"><thead><tr><th>Condition</th><th></th></tr></thead><tbody><tr><td>is empty</td><td>is not empty</td></tr></tbody></table><h3 id="calculated-types" tabindex="-1">Calculated types <a class="header-anchor" href="#calculated-types" aria-label="Permalink to &quot;Calculated types&quot;">​</a></h3><p><strong>Use linked value</strong>, <strong>Calculate sum</strong>, <strong>Formula</strong></p><p>These types can be filtered; the available conditions depend on the <strong>result type</strong>. A formula with a numeric result behaves like a number.</p><div class="warning custom-block"><p class="custom-block-title">Cannot be used as a Flow trigger</p><p>Calculated fields can be filtered, but they <strong>cannot</strong> be used as the triggering field in the <em>Entry was changed</em> Flow trigger. → <a href="/en/flows/trigger">Triggers</a></p></div><hr><h2 id="filter-groups" tabindex="-1">Filter groups <a class="header-anchor" href="#filter-groups" aria-label="Permalink to &quot;Filter groups&quot;">​</a></h2><p>You combine multiple conditions with <strong>and</strong> or <strong>or</strong>. Groups can be nested.</p><div class="warning custom-block"><p class="custom-block-title">Three levels maximum</p><blockquote><p><em>Filter conditions can only be nested 3 levels deep</em></p></blockquote><p>If you need more, create a helper field of type <strong>Formula</strong> or <strong>Checkmark</strong> that captures the complex condition, and filter on that instead.</p></div><p>As long as a condition is incomplete, ApptiveGrid reports <em>All existing filters must be valid</em> and does not apply the filter.</p><hr><h2 id="completeness" tabindex="-1">Completeness <a class="header-anchor" href="#completeness" aria-label="Permalink to &quot;Completeness&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">This mapping is a guide</p><p>This mapping follows the observed behavior of the application. In individual cases, a type may offer an additional condition, or may not offer one listed here.</p><p>What the filter dialog actually offers you is always authoritative.</p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/ansichten/filtern-sortieren-gruppieren">Filtering, Sorting, Grouping</a></li><li><a href="/en/referenz/spaltentypen">Column Types</a></li><li><a href="/en/ansichten/was-ist-eine-ansicht">What is a View</a></li></ul>',62)])])}const g=e(a,[["render",d]]);export{u as __pageData,g as default};
